text:
.cfo-weekly-front{background:#fffaf5;color:#173746;padding:34px 0 26px;border-bottom:1px solid #eadfd5}
.cfo-weekly-front *{box-sizing:border-box}
.cfo-weekly-front .wrap{max-width:1180px;margin:0 auto;padding:0 24px}
.cfo-weekly-head{display:grid;grid-template-columns:1fr auto;gap:18px;align-items:end;margin-bottom:18px}
.cfo-weekly-head h2{margin:0;font:700 clamp(34px,4vw,56px)/.98 Georgia,"Times New Roman",serif;color:#173746}
.cfo-weekly-head p{margin:7px 0 0;max-width:760px;color:#5e686c;font-size:15px}
.cfo-weekly-head>a{color:#8f2e27;font-weight:700;text-decoration:none;border-bottom:1px solid #8f2e27;padding-bottom:2px}
.cfo-weekly-feature{display:grid;grid-template-columns:1.7fr .7fr;gap:12px;margin-bottom:12px;align-items:start}
.cfo-weekly-lead{display:grid;grid-template-columns:190px 1fr;min-height:250px;border:1px solid #e1d7cd;background:#fff}
.cfo-weekly-visual{background:#edf1f1;display:flex;align-items:center;justify-content:center;padding:24px;border-right:1px solid #e1d7cd}
.cfo-weekly-nma{background:linear-gradient(145deg,#eef3f4 0%,#f8f3ed 100%);padding:18px}
.cfo-weekly-nma>div{width:100%;height:100%;min-height:210px;border:1px solid #d9d0c7;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:18px;background:#fffaf5}
.cfo-weekly-nma span{font:700 17px/1 Arial,sans-serif;letter-spacing:.08em;color:#173746}
.cfo-weekly-nma strong{display:block;margin:8px 0 10px;font:700 44px/1 Georgia,"Times New Roman",serif;color:#a53026}
.cfo-weekly-nma em{font:italic 14px/1.35 Georgia,"Times New Roman",serif;color:#4d626b}
.cfo-weekly-copy{padding:25px 28px 22px}
.cfo-weekly-kicker{display:inline-block;background:#a53026;color:#fff;padding:5px 9px;font:700 11px/1 Arial,sans-serif;letter-spacing:.08em;text-transform:uppercase;margin-bottom:12px}
.cfo-weekly-copy h3{margin:0 0 9px;font:700 clamp(30px,3vw,43px)/.98 Georgia,"Times New Roman",serif;color:#173746}
.cfo-weekly-copy p{margin:0 0 14px;font:16px/1.45 Georgia,"Times New Roman",serif;color:#344d58}
.cfo-weekly-actions{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-top:16px}
.cfo-weekly-actions a{font-weight:700;text-decoration:none}
.cfo-weekly-actions .primary{background:#a53026;color:#fff;padding:10px 16px}
.cfo-weekly-actions .secondary{color:#173746;border-bottom:1px solid #173746;padding-bottom:2px}
.cfo-weekly-source{display:block;margin-top:14px;font-size:11px;color:#7a8589}
.cfo-weekly-source a{color:inherit}
.cfo-weekly-pulse{border:1px solid #e1d7cd;background:#fff;padding:18px}
.cfo-weekly-pulse h3{margin:0 0 12px;font:700 23px/1 Georgia,"Times New Roman",serif;color:#173746}
.cfo-weekly-pulse .pulse{display:grid;grid-template-columns:1fr auto;gap:4px 10px;padding:13px 0;border-top:1px solid #eee6de}
.cfo-weekly-pulse .pulse:first-of-type{border-top:0}
.cfo-weekly-pulse span{font-size:12px;color:#6b777b}
.cfo-weekly-pulse strong{font:700 24px/1 Georgia,"Times New Roman",serif;color:#a53026}
.cfo-weekly-pulse em{grid-column:1/-1;font-size:12px;font-style:normal;color:#4d626b}
.cfo-weekly-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.cfo-weekly-card{border:1px solid #e1d7cd;background:#fff;padding:18px 18px 16px;min-height:265px;display:flex;flex-direction:column}
.cfo-weekly-card .label{font:700 11px/1 Arial,sans-serif;letter-spacing:.08em;text-transform:uppercase;color:#a53026;margin-bottom:10px}
.cfo-weekly-card h3{margin:0 0 9px;font:700 24px/1.02 Georgia,"Times New Roman",serif;color:#173746}
.cfo-weekly-card p{margin:0 0 14px;font:14px/1.4 Georgia,"Times New Roman",serif;color:#4c5d64}
.cfo-weekly-metrics{display:grid;gap:7px;margin-top:auto}
.cfo-weekly-metric{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:end;padding-top:7px;border-top:1px solid #eee6de}
.cfo-weekly-metric span{font-size:12px;color:#68767b}
.cfo-weekly-metric strong{font:700 17px/1 Georgia,"Times New Roman",serif;color:#173746}
.cfo-weekly-metric small{grid-column:1/-1;color:#188051;font-size:11px}
.cfo-weekly-card>a{display:inline-block;margin-top:14px;color:#173746;font-weight:700;text-decoration:none;border-bottom:1px solid #173746;align-self:flex-start}
.cfo-weekly-reperes{display:grid;grid-template-columns:180px repeat(5,1fr);gap:1px;background:#ded5cc;border:1px solid #ded5cc;margin-top:12px}
.cfo-weekly-reperes>div{background:#fff;padding:11px 12px;min-height:62px}
.cfo-weekly-reperes .rep-title{background:#f5eee8}
.cfo-weekly-reperes span{display:block;font-size:10px;color:#6b777b}
.cfo-weekly-reperes strong{display:block;margin-top:3px;font:700 18px/1 Georgia,"Times New Roman",serif;color:#173746}
.cfo-weekly-reperes em{display:block;margin-top:3px;font-size:10px;font-style:normal;color:#188051}
@media(max-width:980px){.cfo-weekly-feature{grid-template-columns:1fr}.cfo-weekly-grid{grid-template-columns:1fr 1fr}.cfo-weekly-reperes{grid-template-columns:1fr 1fr 1fr}.cfo-weekly-reperes .rep-title{grid-column:1/-1}}
@media(max-width:680px){.cfo-weekly-front{padding:26px 0 20px}.cfo-weekly-head{grid-template-columns:1fr}.cfo-weekly-lead{grid-template-columns:1fr}.cfo-weekly-visual{min-height:150px;border-right:0;border-bottom:1px solid #e1d7cd}.cfo-weekly-grid{grid-template-columns:1fr}.cfo-weekly-reperes{grid-template-columns:1fr 1fr}.cfo-weekly-copy{padding:21px}.cfo-weekly-front .wrap{padding:0 16px}}

.cfo-card-visual{height:118px;margin:2px 0 14px;overflow:hidden;border:1px solid #e3dbd3;background:#f4efe9}
.cfo-card-visual img{width:100%;height:100%;object-fit:cover;display:block}
.cfo-bars{display:grid;gap:9px;margin-top:auto}
.cfo-bars>div{display:grid;grid-template-columns:88px 1fr 62px;gap:8px;align-items:center}
.cfo-bars span{font-size:11px;color:#4f6169}
.cfo-bars i{display:block;height:8px;background:#e8ecee;border-radius:99px;overflow:hidden}
.cfo-bars b{display:block;height:100%;background:#173746;border-radius:99px}
.cfo-bars strong{font:700 13px/1 Georgia,"Times New Roman",serif;text-align:right;color:#173746}
.cfo-bars small{grid-column:3;font-size:10px;color:#aa352f;text-align:right;margin-top:-5px}
.cfo-audience-mini{display:grid;gap:10px;margin-top:auto}
.cfo-audience-kpi{border:1px solid #ece3db;padding:10px;background:#fbfdfb}
.cfo-audience-kpi span{display:block;font-size:11px;color:#68767b}
.cfo-audience-kpi strong{display:block;margin-top:2px;font:700 20px/1 Georgia,"Times New Roman",serif;color:#173746}
.cfo-audience-kpi small{display:block;margin-top:2px;font-size:10px;color:#188051}
.cfo-audience-kpi svg{width:100%;height:38px;margin-top:5px}
.cfo-audience-kpi polyline{fill:none;stroke:#1b8a56;stroke-width:2.3;vector-effect:non-scaling-stroke}
.cfo-audience-kpi:nth-child(2) polyline{stroke:#a53026}
.cfo-radio-chart{display:grid;gap:8px;margin-top:auto}
.cfo-radio-total{display:grid;grid-template-columns:1fr auto;gap:2px 10px;padding-bottom:8px;border-bottom:1px solid #eee6de}
.cfo-radio-total span{font-size:11px;color:#68767b}
.cfo-radio-total strong{font:700 20px/1 Georgia,"Times New Roman",serif;color:#173746}
.cfo-radio-total small{grid-column:1/-1;font-size:10px;color:#aa352f}
.cfo-radio-chart>div:not(.cfo-radio-total){display:grid;grid-template-columns:88px 1fr 42px;gap:8px;align-items:center}
.cfo-radio-chart>div:not(.cfo-radio-total) span{font-size:11px;color:#4f6169}
.cfo-radio-chart i{display:block;height:8px;background:#f0e7e2;border-radius:99px;overflow:hidden}
.cfo-radio-chart b{display:block;height:100%;background:#a53026;border-radius:99px}
.cfo-radio-chart>div:not(.cfo-radio-total) strong{font:700 13px/1 Georgia,"Times New Roman",serif;text-align:right;color:#173746}

.cfo-spark-bars{height:40px;display:flex;align-items:flex-end;gap:4px;margin-top:8px;padding-top:4px;border-top:1px solid #edf0ee}
.cfo-spark-bars i{flex:1;min-width:3px;background:#1b8a56;border-radius:2px 2px 0 0}
.cfo-spark-bars.youtube i{background:#a53026}
.cfo-weekly-nma{background:#070707!important;padding:10px!important}
.cfo-weekly-nma img{width:100%;height:100%;min-height:250px;object-fit:contain!important;display:block;background:#070707}
.cfo-card-visual{background:#f4efe9!important}
.cfo-card-visual img{display:block!important;width:100%!important;height:100%!important;object-fit:cover!important}

.cfo-weekly-lead{display:block;min-height:0;border:1px solid #e1d7cd;background:#fff}
.cfo-weekly-visual{width:100%;aspect-ratio:16/9;height:auto;padding:0;border-right:0;border-bottom:1px solid #e1d7cd;background:#f2f0ec;display:flex;align-items:center;justify-content:center;overflow:hidden}.cfo-weekly-visual img{width:100%;height:100%;object-fit:cover;display:block}.cfo-weekly-nma{background:#050505!important;padding:12px!important;overflow:hidden}
.cfo-weekly-nma img{width:100%!important;height:100%!important;min-height:0!important;aspect-ratio:auto!important;object-fit:contain!important;object-position:center!important;display:block!important;background:#050505!important}
.cfo-track-banner{height:118px;margin:2px 0 14px;border:1px solid #e3dbd3;background:linear-gradient(135deg,#f5ede8 0%,#fff 55%,#eef3f4 100%);display:grid;grid-template-columns:1fr auto;grid-template-rows:auto auto 1fr;align-items:end;padding:14px 16px;overflow:hidden}
.cfo-track-banner span{grid-column:1/-1;font:700 26px/1 Georgia,"Times New Roman",serif;color:#173746;letter-spacing:.02em}
.cfo-track-banner em{font:700 10px/1 Arial,sans-serif;letter-spacing:.12em;text-transform:uppercase;color:#a53026;font-style:normal;margin-top:6px}
.cfo-track-pulse{grid-column:1/-1;height:36px;display:flex;align-items:flex-end;gap:5px;margin-top:8px}
.cfo-track-pulse i{flex:1;background:#173746;border-radius:2px 2px 0 0}
@media(max-width:980px){.cfo-weekly-lead{grid-template-columns:300px 1fr}}
@media(max-width:680px){.cfo-weekly-lead{grid-template-columns:1fr}.cfo-weekly-visual{border-right:0;border-bottom:1px solid #e1d7cd}.cfo-weekly-visual img,.cfo-weekly-nma img{aspect-ratio:16/9!important}.cfo-weekly-nma img{min-height:0!important;object-fit:contain!important}}
